DIGITS = "0123456789"


def encode(text):
    """Run-length encode text that holds no digits. See TASK.md."""
    for ch in text:
        if ch in DIGITS:
            raise ValueError("text must not contain digits")
    out = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        j = i
        while j < n and text[j] == ch:
            j += 1
        run = j - i
        if run == 1:
            out.append(ch)
        else:
            out.append(str(run))
            out.append(ch)
        i = j
    return "".join(out)


def decode(text):
    """Reverse `encode`. See TASK.md."""
    out = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch not in DIGITS:
            out.append(ch)
            i += 1
            continue
        j = i
        while j < n and text[j] in DIGITS:
            j += 1
        digits = text[i:j]
        if digits[0] == "0":
            raise ValueError("count must not have a leading zero")
        count = int(digits)
        if count < 2:
            raise ValueError("count must be at least 2")
        if j >= n:
            raise ValueError("count has no character after it")
        out.append(text[j] * count)
        i = j + 1
    return "".join(out)
